import gurobipy as gp
from gurobipy import GRB
suppliers = []
dealerships = []
fixed_costs = {}
demands = {}
transportation_costs = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('fixed_cost.csv'):
        sid = vals['Unnamed: 0']
        suppliers.append(sid)
        fixed_costs[sid] = float(vals['fixed_costs'])
    elif src.endswith('demand.csv'):
        cid = vals['customer']
        dealerships.append(cid)
        demands[cid] = int(vals['demand'])
    elif src.endswith('transportation_costs.csv'):
        sid = vals['Unnamed: 0']
        if sid not in transportation_costs:
            transportation_costs[sid] = {}
        for cid in vals:
            if cid.startswith('C'):
                transportation_costs[sid][cid] = float(vals[cid])
suppliers = list(dict.fromkeys(suppliers))
dealerships = list(dict.fromkeys(dealerships))
for s in suppliers:
    if s not in fixed_costs:
        raise ValueError(f'Missing fixed cost for supplier {s}')
    if s not in transportation_costs:
        raise ValueError(f'Missing transportation costs for supplier {s}')
    for c in dealerships:
        if c not in transportation_costs[s]:
            raise ValueError(f'Missing transportation cost for supplier {s}, dealership {c}')
for c in dealerships:
    if c not in demands:
        raise ValueError(f'Missing demand for dealership {c}')
m = gp.Model('Colorado_Motor_Vehicle_Sales')
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, name='')
x_vars = m.addVars(suppliers, dealerships, vtype=GRB.CONTINUOUS, lb=0, name='')
m.setObjective(gp.quicksum((fixed_costs[s] * y_vars[s] for s in suppliers)) + gp.quicksum((transportation_costs[s][c] * x_vars[s, c] for s in suppliers for c in dealerships)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[s, c] for s in suppliers)) == demands[c] for c in dealerships), name='')
m.addConstrs((x_vars[s, c] <= demands[c] * y_vars[s] for s in suppliers for c in dealerships), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')